MAX_JOBS = 6
CAPACITY = 60
SETUP = 3
PENALTY = 2


def batch_cost(durations):
    return SETUP + max(durations) * len(durations)


def plan(durations):
    """Batch sizes, filling each batch as far as the limits allow."""
    sizes, current, total = [], 0, 0
