            candidate = (cost + batch_cost(durations[start:start + size]), batches + 1, [size] + sizes)
            if chosen is None or candidate[:2] < chosen[:2] or (candidate[:2] == chosen[:2]
                                                                and candidate[2] > chosen[2]):
                chosen = candidate
        best[start] = chosen
    return best[0][2]

