import math
import re
from decimal import ROUND_HALF_UP, Decimal

REGION_TAX = {'de': 0.2, 'uk': 0.0825, 'au': 0.19, 'eu': 0.2}
COUPON_PREFIX = "HALF"
DEFAULT_REGION = "au"
QUANTITY = "floor"
PRICE = "number"
ROUND_LINES = False
UNDEFINED = object()
NAN = float("nan")
JS_SPACE = " \t\n\v\f\r\xa0                　﻿"
