        return "undefined"
    if value is None:
        return "null"
    if isinstance(value, bool):
        return "true" if value else "false"
    if isinstance(value, (int, float)):
        return js_number_text(float(value))
    assert isinstance(value, str), f"not a JSON scalar: {value!r}"
    return value


