import unittest

from garnet_bus.decode import decode


class DecodeTests(unittest.TestCase):
    def test_empty_message(self):
        with self.assertRaises(ValueError):
            decode(b"")

    def test_unknown_type(self):
        with self.assertRaises(ValueError):
            decode(bytes([0xFF]))


