        if '"' in text:
            raise ValueError(f"stray quote in {text!r}")
        return text, False
    closing = _closing_quote(text, 0)
    if closing != len(text) - 1:
        raise ValueError(f"text after a closing quote in {text!r}")
    value, index = [], 1
    while index < closing:
        if text[index] == "\\":
            index += 1
        value.append(text[index])
        index += 1
    return "".join(value), True


